window.VENICE_SQL = [{"file": "burns_by_source_daily", "title": "Revenue and one-off burns by source, per day (chapter 03, Monitor)", "sql": "-- schema check 2026-11-13: confirmed base.assets.erc20_token_transfers (block_timestamp, from_address, to_address, token_address, amount) and common.prices.hourly (timestamp, chain, price) | changed common.prices.hourly token_address -> address (docs column is `address`) | docs do not give price's type for common.prices.hourly (base.prices.hourly lists it as VARCHAR; cast if median() errors)\nwith burns as (\n  select date_trunc('day', block_timestamp) as day,\n         from_address,\n         amount\n  from base.assets.erc20_token_transfers\n  where token_address = '0xacfe6019ed1a7dc6f7b508c02d1b04ec88cc21bf'\n    and to_address in ('0x0000000000000000000000000000000000000000', '0x000000000000000000000000000000000000dead')\n), labelled as (\n  select day, amount,\n    case from_address\n      when '0x01784ef301d79e4b2df3a21ad9a536d4cf09a5ce' then 'programmatic'   -- Aerodrome VVV/WETH #2: subscription + API-credit burns\n      when '0x35fb3b67c57849bf57eb24b061eef0b5e560dc57' then 'discretionary'  -- Buy-and-Burn Safe (monthly TWAP)\n      when '0x328d006528faff5167ca1ed5f532c45f6fd08654' then 'airdrop'        -- unclaimed airdrop, 2025-03-12\n      when '0x29bc65e0b05046b4d0896d1f4521b7e3102071df' then 'team'           -- team buyback, 2025-03-12\n      else 'other' end as source\n  from burns\n), px as (\n  select date_trunc('day', timestamp) as day, median(price) as price\n  from common.prices.hourly\n  where chain = 'base' and address = '0xacfe6019ed1a7dc6f7b508c02d1b04ec88cc21bf'\n  group by 1\n)\nselect l.day, l.source, sum(l.amount) as vvv_burned, sum(l.amount * px.price) as usd_burned, count(*) as burn_events\nfrom labelled l left join px using (day)\nwhere l.day < current_date\ngroup by 1, 2\norder by 1, 2;"}, {"file": "staking_daily", "title": "VVV staked: sVVV minted (stake) minus burned (unstake), cumulative (chapter 04)", "sql": "-- schema check 2026-11-13: confirmed base.assets.erc20_token_transfers (block_timestamp, from_address, to_address, token_address, amount) | nothing changed | nothing missing\nwith flows as (\n  select date_trunc('day', block_timestamp) as day,\n         sum(case when from_address = '0x0000000000000000000000000000000000000000' then amount else 0 end)\n       - sum(case when to_address   = '0x0000000000000000000000000000000000000000' then amount else 0 end) as net_staked\n  from base.assets.erc20_token_transfers\n  where token_address = '0x321b7ff75154472b18edb199033ff4d116f340ff'\n    and (from_address = '0x0000000000000000000000000000000000000000' or to_address = '0x0000000000000000000000000000000000000000')\n  group by 1\n)\nselect day, net_staked, sum(net_staked) over (order by day) as vvv_staked\nfrom flows where day < current_date order by day;"}, {"file": "diem_supply_daily", "title": "DIEM outstanding, split by Venice-minted vs everyone else (chapter 05)", "sql": "-- schema check 2026-11-13: confirmed base.assets.erc20_token_transfers (block_timestamp, from_address, to_address, token_address, amount) | nothing changed | nothing missing\nwith venice as (\n  select column1 as address from values\n    ('0x2d8cb8dc596dad0e1e34e2042e7ae6df93b11524'),  -- Genesis Treasury\n    ('0x4665883f3adb708f301ba75764d39ad0cd2a4d84'),  -- Incentive Fund\n    ('0xb6e08047320b4b4d943d7f1363776dddc6f4aa66')   -- Team Ops Safe\n), ev as (\n  select date_trunc('day', block_timestamp) as day,\n         case when from_address = '0x0000000000000000000000000000000000000000' then amount else -amount end as delta,\n         case when from_address = '0x0000000000000000000000000000000000000000' then to_address else from_address end as holder\n  from base.assets.erc20_token_transfers\n  where token_address = '0xf4d97f2da56e8c3098f3a8d538db630a2606a024'\n    and (from_address = '0x0000000000000000000000000000000000000000' or to_address = '0x0000000000000000000000000000000000000000')\n)\nselect day,\n       sum(sum(delta)) over (order by day) as diem_supply,\n       sum(sum(case when holder in (select address from venice) then delta else 0 end)) over (order by day) as diem_minted_by_venice,\n       count_if(delta > 0) as mints\nfrom ev where day < current_date group by day order by day;"}, {"file": "emissions_vs_burns_monthly", "title": "Emitted vs revenue-burned VVV per month, and coverage (chapter 03)", "sql": "-- schema check 2026-11-13: confirmed base.assets.erc20_token_transfers (block_timestamp, from_address, to_address, token_address, amount) | nothing changed | nothing missing\nwith mint as (\n  select date_trunc('month', block_timestamp) as m, sum(amount) as emitted\n  from base.assets.erc20_token_transfers\n  where token_address = '0xacfe6019ed1a7dc6f7b508c02d1b04ec88cc21bf'\n    and from_address = '0x0000000000000000000000000000000000000000'\n    and block_timestamp > '2025-01-24'                       -- exclude the 100M genesis mint\n  group by 1\n), burn as (\n  select date_trunc('month', block_timestamp) as m, sum(amount) as burned_revenue\n  from base.assets.erc20_token_transfers\n  where token_address = '0xacfe6019ed1a7dc6f7b508c02d1b04ec88cc21bf'\n    and to_address in ('0x0000000000000000000000000000000000000000', '0x000000000000000000000000000000000000dead')\n    and from_address not in ('0x328d006528faff5167ca1ed5f532c45f6fd08654', '0x29bc65e0b05046b4d0896d1f4521b7e3102071df')\n  group by 1\n)\nselect m, emitted, coalesce(burned_revenue, 0) as burned_revenue,\n       coalesce(burned_revenue, 0) / nullif(emitted, 0) as burn_coverage,\n       emitted - coalesce(burned_revenue, 0) as net_change_ex_oneoff\nfrom mint left join burn using (m) order by m;"}, {"file": "where_vvv_sits", "title": "Every VVV ever minted in one bucket (chapter 04)", "sql": "-- schema check 2026-11-13: confirmed base.assets.fungible_balances_latest (address, token_address, balance), base.dex.pools (token0_address, token1_address), allium_identity.common.address_labels (chain, address) | changed base.dex.pools address -> liquidity_pool_address; address_labels category -> primary_category (Premium table; Premium taxonomy uses 'exchange', Basic uses 'cex'); qualified address as bal.address (both tables have it) | docs mark address_labels as a paid Premium table, access not confirmed\nwith bal as (\n  select address, balance\n  from base.assets.fungible_balances_latest\n  where token_address = '0xacfe6019ed1a7dc6f7b508c02d1b04ec88cc21bf' and balance > 0\n), lab as (\n  select bal.address,\n    case\n      when bal.address in ('0x0000000000000000000000000000000000000000', '0x000000000000000000000000000000000000dead') then 'Burned'\n      when bal.address = '0x321b7ff75154472b18edb199033ff4d116f340ff' then 'Staking contract'\n      when bal.address in ('0x2d8cb8dc596dad0e1e34e2042e7ae6df93b11524', '0x4665883f3adb708f301ba75764d39ad0cd2a4d84',\n                       '0xb3c89592d84ae6adb6a1aa41515ac14ec822b175', '0xb6e08047320b4b4d943d7f1363776dddc6f4aa66',\n                       '0xf1ef353babfffb09925ef29eccbc1948aedc7720') then 'Venice wallets'\n      when bal.address in (select liquidity_pool_address from base.dex.pools where token0_address = '0xacfe6019ed1a7dc6f7b508c02d1b04ec88cc21bf'\n                                                       or token1_address = '0xacfe6019ed1a7dc6f7b508c02d1b04ec88cc21bf') then 'DEX pools'\n      when l.primary_category in ('cex', 'exchange') then 'Exchanges'\n      else 'Other wallets' end as bucket\n  from bal left join allium_identity.common.address_labels l on l.chain = 'base' and l.address = bal.address\n)\nselect bucket, sum(balance) as vvv from bal join lab using (address) group by 1 order by 2 desc;"}, {"file": "holder_bands_daily", "title": "Holders by balance band over time (whale accumulation check; next version)", "sql": "-- schema check 2026-11-13: confirmed base.assets.fungible_balances_daily (date, address, token_address, balance) | nothing changed | nothing missing (date is TIMESTAMP_NTZ in docs)\nselect date as day,\n  count_if(balance >= 100000) as whales_100k,\n  count_if(balance >= 10000 and balance < 100000) as large_10k,\n  count_if(balance >= 1000 and balance < 10000) as mid_1k,\n  count_if(balance >= 100 and balance < 1000) as small_100,\n  count_if(balance > 0 and balance < 100) as dust,\n  sum(case when balance >= 100000 then balance end) as vvv_in_whales\nfrom base.assets.fungible_balances_daily\nwhere token_address = '0xacfe6019ed1a7dc6f7b508c02d1b04ec88cc21bf'\n  and address not in ('0x321b7ff75154472b18edb199033ff4d116f340ff', '0x0000000000000000000000000000000000000000')\ngroup by 1 order by 1;"}, {"file": "dex_volume_adjusted_daily", "title": "VVV DEX volume, raw vs Allium wash-adjusted (chapter 06 upgrade)", "sql": "-- schema check 2026-11-13: confirmed base.dex.trades_enriched (block_timestamp, usd_amount, usd_amount_adjusted, is_flagged, transaction_from_address, token_bought_address, token_sold_address) | nothing changed | nothing missing\nselect date_trunc('day', block_timestamp) as day,\n       sum(usd_amount) as volume_raw,\n       sum(usd_amount_adjusted) as volume_adjusted,\n       count_if(is_flagged) as flagged_trades,\n       count(distinct transaction_from_address) as traders\nfrom base.dex.trades_enriched\nwhere (token_bought_address = '0xacfe6019ed1a7dc6f7b508c02d1b04ec88cc21bf' or token_sold_address = '0xacfe6019ed1a7dc6f7b508c02d1b04ec88cc21bf')\n  and block_timestamp < current_date\ngroup by 1 order by 1;"}, {"file": "diem_price_daily", "title": "DIEM daily median DEX price and implied credit yield (chapter 05)", "sql": "-- schema check 2026-11-13: confirmed base.dex.trades (block_timestamp, token_bought_address, token_sold_address, token_bought_amount, token_sold_amount, usd_amount) | nothing changed | nothing missing\nselect date_trunc('day', block_timestamp) as day,\n       median(case when token_bought_address = '0xf4d97f2da56e8c3098f3a8d538db630a2606a024' then usd_amount / nullif(token_bought_amount, 0)\n                   else usd_amount / nullif(token_sold_amount, 0) end) as diem_price,\n       365 / nullif(diem_price, 0) as implied_credit_yield\nfrom base.dex.trades\nwhere (token_bought_address = '0xf4d97f2da56e8c3098f3a8d538db630a2606a024' or token_sold_address = '0xf4d97f2da56e8c3098f3a8d538db630a2606a024')\n  and usd_amount > 10 and block_timestamp < current_date\ngroup by 1 order by 1;"}];
